fn compose_nested_route_path(&self, path: &str, nested_path: &str) -> String {
    if nested_path == "/" {
        path.to_owned()
    } else if path == "/" {
        // avoid the mount path and the nested path both contributing a
        // leading slash, e.g. `nest("/", Router::new().route("/foo", _))`
        // should route `/foo` and not `//foo`
        nested_path.to_owned()
    } else {
        Self::join_mount_and_nested(path, nested_path)
    }
}

